// Validate Input

const req = $json;

// clientId from URL param
const clientId = (req.params?.clientId || '').trim();

// message from JSON body
const message = (req.body?.message || '').trim();

// headers
const headers = req.headers || {};

// sessionId: from body or header if provided
const sessionId =
  (req.body?.sessionId || '').toString().trim() ||
  (headers['x-session-id'] || headers['X-Session-Id'] || '').toString().trim();

if (!clientId || !message) {
  return [{
    json: {
      error: true,
      message: 'Missing clientId or message.'
    }
  }];
}

return [{
  json: {
    clientId,
    message,
    headers,
    sessionId,
  }
}];

// FORMAT RESPONSE
// Normalizes the LLM reply into a clean `message` string:
// - Handles OpenAI/Groq-style responses
// - Fixes double-escaped unicode like \u0027
// - Fixes \n shown as literal backslash-n

let content = '';

// 1) Common shapes: if you've already mapped or picked earlier
if (typeof $json.message === 'string' && $json.message.trim() !== '') {
  content = $json.message;
} else if (typeof $json.answer === 'string' && $json.answer.trim() !== '') {
  content = $json.answer;

// 2) Direct OpenAI/Groq style
} else if (Array.isArray($json.choices)
  && $json.choices[0]
  && $json.choices[0].message
  && typeof $json.choices[0].message.content === 'string') {

  content = $json.choices[0].message.content;

// 3) Nested data.choices (if HTTP node wraps it)
} else if ($json.data
  && Array.isArray($json.data.choices)
  && $json.data.choices[0]
  && $json.data.choices[0].message
  && typeof $json.data.choices[0].message.content === 'string') {

  content = $json.data.choices[0].message.content;
}

// If nothing found, return debug once so you can see shape
if (!content) {
  return [{
    json: {
      message: 'No content found in LLM response.',
      debug: $json
    }
  }];
}

// At this point `content` is whatever the model returned.
// If you're seeing \u0027 in the final API response, that means your string
// literally contains the characters "\u0027" (double-escaped).
// So we target the BACKSLASHED form: \\u0027, not real \u0027.

content = content
  // double-escaped unicode sequences → real characters
  .replace(/\\u0027/g, "'")
  .replace(/\\u2019/g, "’")
  .replace(/\\u2018/g, "‘")
  .replace(/\\u201c/g, "“")
  .replace(/\\u201d/g, "”")
  .replace(/\\u003c/g, "<")
  .replace(/\\u003e/g, ">")
  .replace(/\\u0026/g, "&")
  // double-escaped newlines / tabs → real
  .replace(/\\n/g, "\n")
  .replace(/\\t/g, "\t");

// Safety: strip outer quotes if the whole thing is still quoted like a JSON string
if (
  content.length >= 2 &&
  content.startsWith('"') &&
  content.endsWith('"')
) {
  content = content.slice(1, -1);
}

// Final cleanup
content = content.trim();

return [{
  json: {
    message: content
  }
}];

// Validate Input Error
// Triggered when request is malformed (missing clientId/message, bad JSON, etc.)

return [{
  json: {
    error: true,
    code: 'VALIDATION_FAILED',
    message: 'There was an error validating your input. Please contact the website owner',
    origin: 'Validate Input',
    debug: $json
  }
}];

// Sheets Config Error
// Triggered when we can't read the client config row

// Try to grab clientId/message from Validate Input if available
const base = $node['Validate Input']?.json || {};

return [{
  error: true,
  code: 'SHEETS_LOOKUP_FAILED',
  message: 'There was an error in retrieving client data. Please contact site owner.',
  origin: 'Google Sheets Lookup',
  clientId: base.clientId || null,
  debug: $json
}];

// Build Prompt Error
// Triggered when prompt construction fails (usually bad/missing config)

const base = $node['Validate Input']?.json || {};

return [{
  error: true,
  code: 'BUILD_PROMPT_FAILED',
  message: 'A problem occurred while building the prompt. Please contact site owner.',
  origin: 'Build Prompt',
  clientId: base.clientId || null,
  debug: $json
}];

// LLM Error
// Triggered when Groq/OpenAI/etc fails (401, 429, timeout, etc.)

const base = $node['Validate Input']?.json || {};
const details = $json || {};

return [
  {
    json: {
      error: true,
      code: 'LLM_API_ERROR',
      message: 'A problem occurred while calling the LLM. Please contact site owner.',
      origin: 'Call LLM',
      clientId: base.clientId || null,
      debug: details
    }
  }
];

// Format Error
// Triggered when LLM response doesn't match expected shape

const base = $node['Validate Input']?.json || {};

return [{
  json: {
    error: true,
    code: 'LLM_RESPONSE_INVALID',
    message: 'A problem occurred while formatting the answer. Please contact site owner.',
    origin: 'Format Response',
    clientId: base.clientId || null,
    debug: $json
  }
}];

// This must always output an array of { json: { ... } }

const msg =
  $json.message ||
  $json.answer ||
  'No message available.';

return [{
  json: {
    message: msg
  }
}];

// Select Client Config
// Input: all rows from the config sheet (each item.json is a row)
// Also uses clientId from "Validate Input"

const validate = $node['Validate Input'].json;
const clientId = (validate.clientId || '').trim();

// Always get ALL incoming items from Sheets
const rows = $input.all();

// If Sheets returned nothing at all (real failure or empty sheet)
if (!rows || rows.length === 0) {
  return [{
    json: {
      error: true,
      message: 'Config sheet is empty or not readable.',
      source: 'Select Client Config'
    }
  }];
}

// If somehow no clientId, bail clearly
if (!clientId) {
  return [{
    json: {
      error: true,
      message: 'Invalid request. Missing clientId.',
      source: 'Select Client Config'
    }
  }];
}

// Try to find a matching row
let match = null;

for (const item of rows) {
  const rowId = (item.json.clientId || '').trim();
  if (rowId && rowId === clientId) {
    match = item.json;
    break;
  }
}

// If no matching row -> return ONE error item
if (!match) {
  return [{
    json: {
      error: true,
      message: 'There was an error in retrieving client data. Please contact site owner.',
      source: 'Select Client Config'
    }
  }];
}

// If found -> return ONE clean item with that row's data
return [{
  json: match
}];

// Sheets Config Error
// Triggered when we can't read the client config row

// Try to grab clientId/message from Validate Input if available
const base = $node['Validate Input']?.json || {};

return [{
  error: true,
  code: 'SHEETS_LOOKUP_FAILED',
  message: 'There was an error in retrieving client data. Please contact site owner.',
  origin: 'Google Sheets Lookup',
  clientId: base.clientId || null,
  debug: $json
}];

// Select Client From Registry & validate token

const validate = $node['Validate Input'].json;

const clientId = (validate.clientId || '').trim();
const headers = validate.headers || {};
const providedToken = (headers['x-client-token'] || headers['X-Client-Token'] || '').trim();

// All registry rows from previous node
const rows = $input.all();

let match = null;
for (const item of rows) {
  const row = item.json;
  const rowClientId = (row.clientId || '').trim();
  if (rowClientId === clientId) {
    match = row;
    break;
  }
}

// No such client
if (!match) {
  return [{
    json: {
      error: true,
      message: 'Unregistered or misconfigured client.',
      debug: { clientId, providedToken }
    }
  }];
}

const expectedToken = (match.token || '').trim();

// Token mismatch
if (expectedToken && providedToken !== expectedToken) {
  return [{
    json: {
      error: true,
      message: 'Unauthorized. Invalid or missing client token.',
      debug: { clientId, providedToken, expectedToken }
    }
  }];
}

// Success: ONLY this client's row moves on
return [{
  json: match
}];

const clientId = ($node['Validate Input'].json.clientId || '').trim();
const rows = $input.all();

let match = null;
for (const item of rows) {
  const row = item.json;
  if ((row.clientId || '').trim() === clientId) {
    match = row;
    break;
  }
}

if (!match) {
  return [{
    json: {
      error: true,
      message: 'Unregistered or misconfigured client.'
    }
  }];
}

return [{
  json: match
}];

// Authentication Error
// Triggered when request does not have everything required for authentication (header, token, etc.)

return [{
  json: {
    error: true,
    code: 'AUTHENTICATION_FAILED',
    message: 'There was an error authenticating your request. Please contact the website owner',
    origin: 'Select Client From Registry',
    debug: $json
  }
}];

//--------------------------------------------------
// Rate Limiter — per client + per session
//--------------------------------------------------

const clientId = $json.clientId || 'unknown';
let sessionId = $json.sessionId;

// Fallback if no sessionId provided (not ideal for prod, fine as backup)
if (!sessionId) {
  const ip =
    $json.headers?.['x-forwarded-for'] ||
    $json.headers?.['x-real-ip'] ||
    'unknown';
  sessionId = `${clientId}_${ip}`;
}

const windowMs = 3000; // 3 seconds per (clientId, sessionId)
const now = Date.now();

const store = $getWorkflowStaticData('global');
const key = `rl_${clientId}_${sessionId}`;
const last = store[key] || 0;
const diff = now - last;

// If this is a repeat inside the window → BLOCK
if (diff < windowMs) {
  return [{
    json: {
      message: 'Too many requests — please wait a few seconds before sending another message.',
      rateLimit: true,
      waitRemainingMs: windowMs - diff,
      debug: {
        key,
        last,
        now,
        diff
      }
    }
  }];
}

// Otherwise → update and continue
store[key] = now;
return $input.all();

// Rate Limit
// Triggered when too many requests are made within 3 secs of each other

return [{
  json: {
    error: true,
    code: 'TOO_MANY_REQUESTS',
    message: 'Too many requests — please wait a few seconds before sending another message.',
    origin: 'Rate Limiter',
    debug: $json
  }
}];

//--------------------------------------------------
// Guardrail Code Node
// - Reads the user message from Validate Input or $json
// - Detects profanity, sexual content, self harm
// - Returns:
//    blocked: true|false
//    category: 'self-harm' | 'content' | null
//    message: final text that should go back to the user (if blocked)
//    sanitizedMessage: original or masked version for logs
//--------------------------------------------------

const validate = $node['Validate Input']?.json || {};
const rawInput =
  (validate.message || $json.message || '').toString();

const msgLower = rawInput.toLowerCase();

// Helper: whole word / phrase match
const containsAny = (text, list) => {
  return list.some(pattern => {
    if (pattern instanceof RegExp) {
      return pattern.test(text);
    }
    const escaped = pattern.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const re = new RegExp(`\\b${escaped}\\b`, "i");
    return re.test(text);
  });
};

// Optional: mask words in sanitizedMessage for logs
const maskWords = (text, list) => {
  let result = text;
  for (const word of list) {
    if (typeof word !== 'string' || !word.trim()) continue;
    const escaped = word.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const re = new RegExp(`\\b${escaped}\\b`, "gi");
    result = result.replace(re, match => "*".repeat(match.length));
  }
  return result;
};

// 1) Profanity (strong terms only)
const profanityList = [
  "fuck",
  "fucking",
  "motherfucker",
  "motherfucking",
  "shit",
  "bullshit",
  "dickhead",
  "asshole",
  "cocksucker",
  "bitch",
  "son of a bitch",
  "cunt",
  "dick",
  "nigger",
  "nigga",
  "dick sucker",
  "dicksucker"
];

// 2) Sexual content (clearly explicit)
const sexualList = [
  "pornhub",
  "porn hub",
  "xvideos",
  "onlyfans",
  "only fans",
  "deepthroat",
  "deep throat",
  "handjob",
  "hand job",
  "blow job",
  "blowjob",
  "cumshot",
  "cum shot",
  "gangbang",
  "gang bang",
  "bdsm",
  "sex tape",
  "cum",
  "kink",
  "kinky",
  "fetish",
  "fetishize"
];

// 3) Self harm signals
const selfHarmList = [
  "kill myself",
  "killing myself",
  "end my life",
  "suicidal",
  "commit suicide",
  "want to die",
  "want to end it all",
  "cut myself",
  "self harm",
  "self-harm",
  "suicide"
];

const isProfanity = containsAny(msgLower, profanityList);
const isSexual   = containsAny(msgLower, sexualList);
const isSelfHarm = containsAny(msgLower, selfHarmList);

// Build a sanitized copy for logging
const sanitized = maskWords(rawInput, [...profanityList, ...sexualList]);

// Self harm: override everything
if (isSelfHarm) {
  return [{
    json: {
      blocked: true,
      category: 'self-harm',
      message:
        "I'm really sorry you're feeling this way. I'm not able to help in crises. If you are having any thoughts of suicide please call or text 988.",
      sanitizedMessage: sanitized
    }
  }];
}

// Explicit sexual or heavy profanity: block or deflect
if (isSexual || isProfanity) {
  return [{
    json: {
      blocked: true,
      category: 'content',
      message:
        "I can't continue with that kind of language or content. If you have a question about the business, services, or booking, I'm happy to help.",
      sanitizedMessage: sanitized
    }
  }];
}

// Otherwise: not blocked, pass through
return [{
  json: {
    blocked: false,
    // Keep both original and sanitized available for later if you want to use them
    message: rawInput,
    sanitizedMessage: sanitized
  }
}];

// Build Prompt node
// Runs AFTER Google Sheets lookup
// Uses:
//  - Config from Sheets (name, style, knowledge, guardrails)
//  - Original clientId + message from "Validate Input"

// 1) Get original data from Validate Input node
const validate = $item(0).$node['Validate Input'].json;

const clientId = (validate.clientId || $json.clientId || '').trim();
const message = (validate.message || $json.message || '').trim();

// 2) Get config from Google Sheets row
const name = ($json.name || '').trim();
const style = ($json.style || 'Clear and helpful.').trim();
const knowledge = ($json.knowledge || '').trim();
const guardrails = ($json.guardrails || 'If unsure, say you are not sure and direct the user to contact the business.').trim();

// 3) Hard validation
if (!clientId) {
  throw new Error('Internal error: missing clientId in Build Prompt.');
}

if (!message) {
  throw new Error('Internal error: missing message in Build Prompt.');
}

if (!name || !knowledge) {
  // Sheet row exists but missing critical fields
  return [
    {
      json: {
        error: true,
        code: 'CLIENT_CONFIG_INCOMPLETE',
        message: 'This assistant is missing required configuration in Google Sheets. Please contact the site owner.'
      }
    }
  ];
}

// 4) Build system prompt
const systemPrompt = `You are an AI assistant for ${name}.
Tone: ${style}
Business info (source of truth): ${knowledge}
Guardrails: ${guardrails}
Rules:
- Answer ONLY questions related to this business and closely relevant topics.
- Do not make up facts. If info is missing, say you are not certain and suggest contacting the business.
- Keep responses concise and clear.`;

// 5) Return clean payload for HTTP Request node
return [
  {
    json: {
      clientId,
      body: {
        model: 'llama-3.1-8b-instant',
        messages: [
          { role: 'system', content: systemPrompt },
          { role: 'user', content: message }
        ],
        max_tokens: 400,
        temperature: 0.4
      }
    }
  }
];
